body.vi:
Khi một hàm hoặc thao tác nghiệp vụ cần tương tác trực tiếp với các thành phần riêng tư (`private`) của từ hai lớp trở lên (ví dụ: lớp `A`, `B`, `C` hoặc phép toán giữa `MT` và `VT`), hàm đó có thể được khai báo với từ khóa `friend` bên trong thân của từng lớp tương ứng.

Tuy nhiên, điều này tạo ra sự phụ thuộc chéo về kiểu dữ liệu: lớp này cần tham chiếu đến lớp kia trong danh sách tham số trước khi lớp kia được định nghĩa đầy đủ. Để giải quyết, trình biên dịch yêu cầu kỹ thuật **khai báo trước (forward declaration)**:
```cpp
class B; // Báo trước cho trình biên dịch rằng B là một kiểu lớp sẽ định nghĩa sau
class A {
    friend void f(const A &a, const B &b);
};
class B {
    friend void f(const A &a, const B &b);
};
```
Sau khi cả hai lớp đã được định nghĩa đầy đủ cấu trúc bộ nhớ và các trường dữ liệu, thân hàm `f(...)` mới được cài đặt để truy cập trực tiếp các thuộc tính ẩn.

body.en:
When an operation requires direct access to private members of two or more distinct classes (e.g., classes `A`, `B`, `C`, or operations coupling `MT` and `VT`), the function can be granted friendship by declaring it with the `friend` keyword inside each class definition.

This creates a mutual type dependency: one class signature references another before the latter is fully defined. To resolve this, C++ requires **forward declarations**:
```cpp
class B; // Informs the compiler that B is a class type to be defined later
class A {
    friend void f(const A &a, const B &b);
};
class B {
    friend void f(const A &a, const B &b);
};
```
The function body `f(...)` must be implemented only after both classes are fully defined so that all private field layouts are known to the compiler.

example.code:
#include <iostream>
#include <vector>

class VT;
class MT;

class VT {
private:
    int n;
    std::vector<double> x;

public:
    VT() : n(0) {}
    VT(int size) : n(size), x(size, 0.0) {}

    void nhapsl(std::istream &in) {
        in >> n;
        x.resize(n);
        for (int i = 0; i < n; ++i) {
            in >> x[i];
        }
    }

    friend void in(const VT &v);
    friend VT tich(const MT &a, const VT &v);
};

class MT {
private:
    int n;
    std::vector<std::vector<double>> a;

public:
    MT() : n(0) {}
    MT(int size) : n(size), a(size, std::vector<double>(size, 0.0)) {}

    void nhapsl(std::istream &in) {
        in >> n;
        a.assign(n, std::vector<double>(n, 0.0));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                in >> a[i][j];
            }
        }
    }

    friend void in(const MT &m);
    friend VT tich(const MT &a, const VT &v);
};

VT tich(const MT &a, const VT &v) {
    if (a.n != v.n) {
        return v;
    }
    VT y(a.n);
    for (int i = 0; i < a.n; ++i) {
        y.x[i] = 0.0;
        for (int j = 0; j < a.n; ++j) {
            y.x[i] += a.a[i][j] * v.x[j];
        }
    }
    return y;
}

void in(const VT &v) {
    for (int i = 0; i < v.n; ++i) {
        std::cout << v.x[i] << (i + 1 == v.n ? "" : " ");
    }
    std::cout << "\n";
}

void in(const MT &m) {
    for (int i = 0; i < m.n; ++i) {
        for (int j = 0; j < m.n; ++j) {
            std::cout << m.a[i][j] << (j + 1 == m.n ? "" : " ");
        }
        std::cout << "\n";
    }
}

int main() {
    MT a;
    VT x;
    a.nhapsl(std::cin);
    x.nhapsl(std::cin);

    VT y = tich(a, x);

    std::cout << "Ma tran A:\n";
    in(a);
    std::cout << "Vec to x:\n";
    in(x);
    std::cout << "Vec to y = Ax:\n";
    in(y);

    return 0;
}
